def _resolve_workplan(plan) -> object | None:
    """Return the workplan from plan or plan.strategy.parallelisable_workplan."""
    workplan = getattr(plan, "workplan", None)
    if not workplan:
        strategy = getattr(plan, "strategy", None)
        if strategy:
            workplan = getattr(strategy, "parallelisable_workplan", None)
    return workplan


def _collect_coder_tasks(groups: list) -> list:
    """Flatten all tasks from workgroup groups."""
    tasks: list = []
    for group in groups or []:
        tasks.extend(getattr(group, "tasks", []) or [])
    return tasks


